(function(){
const TARGETS=new Set(["karen_sanchez","rodrigo_gonzalez","leonardo_gonzalez","omar_azi","rafa_hernandez","scarlet_arianna","anna_georgia","patricio_leigh","maria_ponce","leticia_erguera","nancy_vermilus","ximena_palacios"]);
function current(){return new URL(location.href).searchParams.get("alumno")||""}
function locale(){return current()==="anna_georgia"?"en":current()==="nancy_vermilus"?"fr":"es"}
function esc(v){const d=document.createElement("div");d.textContent=String(v??"");return d.innerHTML}
function clean(t){return String(t||"").replace(/\s+/g," ").trim().replace(/[.]$/,"").trim()}
function splitTasks(t){const raw=clean(t);return raw?raw.split(/\s*\|\s*/).map(clean).filter(Boolean):[]}
function parts(raw){let t=clean(raw),title=t,sub="",detail="";const at=t.indexOf(":");if(at>=0){title=clean(t.slice(0,at));detail=clean(t.slice(at+1))}const src=at>=0?title:t;const p=src.match(/^(.*?)\s*\(([^()]*)\)$/);if(p){title=clean(p[1]);sub=clean(p[2])}else if(at<0){const q=t.match(/^(.*?)\s*\(([^()]*)\)\s*(.*)$/);if(q){title=clean(q[1]);sub=clean(q[2]);detail=clean(q[3])}}return{title,sub,detail}}
function task(raw){const p=parts(raw);return `<article class="poomsaeTask"><p class="poomsaeTaskTitle">${esc(p.title||raw)}</p>${p.sub?`<p class="poomsaeTaskSub">${esc(p.sub)}</p>`:""}${p.detail?`<p class="poomsaeTaskDetail">${esc(p.detail)}</p>`:""}</article>`}
function labels(l,count){if(l==="en")return{empty:"No Poomsae work assigned for this cycle.",date:"Training day",count:`${count} ${count===1?"task":"tasks"}`};if(l==="fr")return{empty:"Aucun travail de Poomsae n’est assigné pour ce cycle.",date:"Jour d’entraînement",count:`${count} ${count===1?"tâche":"tâches"}`};return{empty:"No hay trabajo de Poomsae asignado en este ciclo.",date:"Día de entrenamiento",count:`${count} ${count===1?"tarea":"tareas"}`}}
function render(items,l){if(!Array.isArray(items)||!items.length)return `<div class="poomsaeEmpty">${labels(l,0).empty}</div>`;return `<div class="poomsaeSchedule">${items.map(i=>{const tasks=splitTasks(i?.enfoque||i?.focus||"");const fallback=tasks.length?tasks:[clean(i?.reps||"")].filter(Boolean);const lab=labels(l,fallback.length);const date=i?.titulo||i?.title||i?.dia||i?.dias||lab.date;const note=clean(i?.reps||"");return `<article class="poomsaeDayCard"><div class="poomsaeDayHead"><h4 class="poomsaeDayDate">${esc(date)}</h4><span class="poomsaeDayCount">${esc(lab.count)}</span></div><div class="poomsaeTaskGrid">${fallback.map(task).join("")}</div>${note?`<p class="poomsaeDayNote">${esc(note)}</p>`:""}</article>`}).join("")}</div>`}
function apply(plan){if(!TARGETS.has(current()))return;const body=document.getElementById("poomsae")?.querySelector(".sectionBody");if(body)body.innerHTML=render(Array.isArray(plan?.poomsae)?plan.poomsae:[],locale())}
const prev=typeof renderPage==="function"?renderPage:null;if(prev){renderPage=function(plan,alumno){const result=prev(plan,alumno);apply(plan);return result}}
})();